  RD_K_PROC: 1.5,
  EFFICIENCY_DECAY: 0.02,
  EFFICIENCY_FLOOR: 0.55,
  THROUGHPUT_EXP: 0.50,
  LAUNCH_COST: 180000.0,
  MAX_PRODUCTS: 3,           // more than three lines is bookkeeping, not strategy
