  RATE_BASE: 0.04,           // a company with no debt and profits behind it
  RATE_LEVERAGE: 0.10,       // ...rising with how much of the credit line is used
  RATE_LEVERAGE_EXP: 1.40,   // slowly at first, then quickly
  RATE_LOSSES: 0.05,         // ...and again if the business is losing money
  RATE_LOSS_REF: 80000.0,    // a loss this size counts as fully impaired
  RATE_LOSS_FLOOR: 0.20,     // ...but losses only bite in proportion to what is owed
  RATE_MAX: 0.22,            // the point past which nobody would lend at all
