  AD_GAMMA: 0.8,          // ...and to awareness
  CATEGORY_ELAST: 0.8,    // cheap prices barely grow the category; they steal share
  AD_K: 8.0,
  AD_DECAY: 0.55,         // awareness is rented, not owned
